commands.command:
cat > /etc/nginx/http.d/fleet-tls.conf <<'EOF'
server {
    listen 8443 ssl;
    server_name node2;

    ssl_certificate     /etc/nginx/ssl/node2.crt;
    ssl_certificate_key /etc/nginx/ssl/node2.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    location / {
        return 200 "Fleet Internal CA TLS OK on node2\n";
        add_header Content-Type text/plain;
    }
}
EOF
nginx -t
